<?php
declare(strict_types=1);require_once __DIR__.'/auth.php';require_login();$pdo=db();
if(!user_can('settings.manage')){http_response_code(403);die('Access denied.');}
if(!table_exists($pdo,'settings'))redirect('upgrade_enterprise.php');
$msg=flash('success');
$keys=['app_currency','invoice_default_due_days','service_automation_enabled','bank_statement_default_year','notifications_enabled','layout_sidebar','layout_compact','layout_theme','layout_accent','layout_density','layout_dashboard_style'];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();foreach($keys as $k){$v=post_string($k);$s=$pdo->prepare('INSERT INTO settings(setting_key,setting_value,is_secret,updated_by) VALUES(?,?,0,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),updated_by=VALUES(updated_by)');$s->execute([$k,$v,current_user()['id']]);}activity($pdo,'update','settings',null,'CRM layout/system settings updated');flash('success','Settings saved.');redirect('settings.php');}
$settings=[];foreach($pdo->query('SELECT setting_key,setting_value FROM settings') as $r)$settings[$r['setting_key']]=$r['setting_value'];
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Settings · SPS CRM</title><link rel="stylesheet" href="css/sps-shell.css"><style>body{margin:0;background:#06101d;color:#edf6ff;font-family:Arial}.page{max-width:1000px;margin:auto;padding:22px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.card{background:#102742cc;border:1px solid #ffffff15;border-radius:18px;padding:22px}.field{margin:12px 0}.field label{display:block;font-size:10px;color:#8ea6bd;text-transform:uppercase;letter-spacing:.1em;font-weight:800;margin-bottom:6px}.field input,.field select{width:100%;padding:11px;box-sizing:border-box;background:#ffffff08;color:#fff;border:1px solid #ffffff18;border-radius:10px}.btn{background:#315ee7;color:#fff;padding:11px 14px;border-radius:10px;border:1px solid #6ea8ff55;font-weight:800}.success{background:#4de3a512;color:#8cf4c7;padding:10px;border-radius:10px;margin-bottom:14px}@media(max-width:800px){.grid{grid-template-columns:1fr}}</style></head><body class="sps-shell-page"><aside class="sps-sidebar"><div class="sps-sidebar-brand"><div class="sps-logo-orb">S</div><div class="sps-brand-text"><strong>SPS CRM</strong><span>2050 OPERATIONS CORE</span></div><button class="sps-sidebar-toggle" id="spsSidebarToggle">☰</button></div><?php include __DIR__.'/sidebar_nav.php';?></aside><div class="sps-shell-main"><div class="sps-shell-topbar"><div class="sps-breadcrumbs">SPS CRM / Settings</div><button id="spsMobileMenu" class="sps-sidebar-mobile-toggle">☰</button></div><main class="page"><h1>CRM Control Plane</h1><p class="muted">Layout, finance and automation defaults stored in the database.</p><?php if($msg):?><div class="success"><?=e($msg)?></div><?php endif;?><form method="post"><?=csrf_field()?><div class="grid"><section class="card"><h2>2050 Layout</h2><div class="field"><label>Sidebar</label><select name="layout_sidebar"><option value="expanded" <?=($settings['layout_sidebar']??'expanded')==='expanded'?'selected':''?>>Expanded</option><option value="collapsed" <?=($settings['layout_sidebar']??'expanded')==='collapsed'?'selected':''?>>Collapsed</option></select></div><div class="field"><label>Compact Navigation</label><select name="layout_compact"><option value="0">Comfortable</option><option value="1" <?=($settings['layout_compact']??'0')==='1'?'selected':''?>>Compact</option></select></div><div class="field"><label>Theme</label><select name="layout_theme"><option value="dark">Future Dark</option><option value="midnight" <?=($settings['layout_theme']??'')==='midnight'?'selected':''?>>Midnight</option></select></div><div class="field"><label>Accent</label><select name="layout_accent"><option>cyan</option><option>blue</option><option>violet</option><option>green</option></select></div><div class="field"><label>Density</label><select name="layout_density"><option>comfortable</option><option>compact</option></select></div><div class="field"><label>Dashboard</label><select name="layout_dashboard_style"><option>command</option><option>classic</option></select></div></section><section class="card"><h2>System Defaults</h2><div class="field"><label>Currency</label><input name="app_currency" value="<?=e($settings['app_currency']??'USD')?>"></div><div class="field"><label>Invoice Due Days</label><input type="number" name="invoice_default_due_days" value="<?=e($settings['invoice_default_due_days']??'30')?>"></div><div class="field"><label>Automation</label><select name="service_automation_enabled"><option value="1">Enabled</option><option value="0" <?=($settings['service_automation_enabled']??'1')==='0'?'selected':''?>>Disabled</option></select></div><div class="field"><label>Bank Statement Year</label><input type="number" name="bank_statement_default_year" value="<?=e($settings['bank_statement_default_year']??date('Y'))?>"></div><div class="field"><label>Notifications</label><select name="notifications_enabled"><option value="1">Enabled</option><option value="0" <?=($settings['notifications_enabled']??'1')==='0'?'selected':''?>>Disabled</option></select></div></section></div><div style="text-align:right;margin-top:16px"><button class="btn">Save Configuration</button></div></form></main></div><script>document.addEventListener('DOMContentLoaded',()=>{const s=document.querySelector('.sps-sidebar'),t=document.getElementById('spsSidebarToggle'),m=document.getElementById('spsMobileMenu');if(t)t.onclick=()=>s.classList.toggle('is-collapsed');if(m)m.onclick=()=>s.classList.toggle('open')});</script></body></html>
